import React from 'react';
import CodeBlock from '@theme/CodeBlock';
// @ts-ignore — generated by `npm run build:plugin-godocs` (from docs/site) from
// server/public/plugin; gitignored build output, see docs/site/.gitignore.
import rawDocs from '@site/data/plugin-godocs.json';
import type {GoDocs, GoInterfaceDocs} from './types';
import {signatureText} from './types';
import styles from './styles.module.css';

const docs: GoDocs | undefined = rawDocs && Object.keys(rawDocs).length > 0 ? (rawDocs as GoDocs) : undefined;

function MissingDataNotice() {
  return (
    <p>
      Run <code>npm run build:plugin-godocs</code> (from <code>docs/site</code>) to generate this
      documentation.
    </p>
  );
}

function InterfaceTOC({name, iface}: {name: string; iface: GoInterfaceDocs}) {
  const methods = iface.Methods ?? [];
  const untagged = methods.filter((m) => !m.Tags || m.Tags.length === 0);
  const tags = iface.Tags ?? [];

  return (
    <ul className={styles.toc}>
      {untagged.map((m) => (
        <li key={m.Name}>
          <a href={`#${name}.${m.Name}`}>{signatureText(m)}</a>
        </li>
      ))}
      {tags.map((tag) => (
        <li key={tag}>
          {tag}
          <ul>
            {methods
              .filter((m) => m.Tags?.includes(tag))
              .map((m) => (
                <li key={m.Name}>
                  <a href={`#${name}.${m.Name}`}>{signatureText(m)}</a>
                </li>
              ))}
          </ul>
        </li>
      ))}
    </ul>
  );
}

function InterfaceOverview({name, iface}: {name: string; iface: GoInterfaceDocs}) {
  if (!iface.HTML && (!iface.Methods || iface.Methods.length === 0)) return null;
  return (
    <div>
      <h2 id={name}>{name}</h2>
      {iface.HTML && <div dangerouslySetInnerHTML={{__html: iface.HTML}} />}
      <InterfaceTOC name={name} iface={iface} />
    </div>
  );
}

function InterfaceMethodDocs({name, iface}: {name: string; iface: GoInterfaceDocs}) {
  const methods = iface.Methods ?? [];
  if (methods.length === 0) return null;
  return (
    <div>
      <h2>{name}</h2>
      {methods.map((m) => (
        <div key={m.Name} className={styles.method}>
          <h3 id={`${name}.${m.Name}`}>
            ({name}) {m.Name}
          </h3>
          <CodeBlock language="go">{signatureText(m)}</CodeBlock>
          {m.HTML && <div dangerouslySetInnerHTML={{__html: m.HTML}} />}
        </div>
      ))}
    </div>
  );
}

function exampleEntries(examples: Record<string, {HTML: string; Code: string}>) {
  return Object.entries(examples ?? {}).filter(([name]) => name.startsWith('_'));
}

function ExamplesTOC({examples}: {examples: Record<string, {HTML: string; Code: string}>}) {
  const entries = exampleEntries(examples);
  if (entries.length === 0) return null;
  return (
    <div>
      <h2 id="Examples">Examples</h2>
      <ul className={styles.toc}>
        {entries.map(([name]) => (
          <li key={name}>
            <a href={`#Examples.${name}`}>{displayName(name)}</a>
          </li>
        ))}
      </ul>
    </div>
  );
}

function ExamplesDocs({examples}: {examples: Record<string, {HTML: string; Code: string}>}) {
  const entries = exampleEntries(examples);
  if (entries.length === 0) return null;
  return (
    <div>
      <h2>Examples</h2>
      {entries.map(([name, example]) => (
        <div key={name} className={styles.method}>
          <h3 id={`Examples.${name}`}>(Example) {displayName(name)}</h3>
          {example.HTML && <div dangerouslySetInnerHTML={{__html: example.HTML}} />}
          <CodeBlock language="go">{example.Code}</CodeBlock>
        </div>
      ))}
    </div>
  );
}

function displayName(name: string): string {
  const stripped = name.replace(/^_/, '');
  return stripped.charAt(0).toUpperCase() + stripped.slice(1);
}

/**
 * Renders the full server plugin SDK reference (API / Hooks interfaces, plus runnable examples)
 * generated from `server/public/plugin`'s Go doc comments by `gen-plugin-godocs`. Port of the old
 * mattermost-developer-documentation Hugo `plugingodocs` shortcode.
 *
 * Unlike the old shortcode, method signatures are rendered as plain, syntax-highlighted Go code
 * (via the site's standard `CodeBlock`) rather than HTML with inline pkg.go.dev links baked into
 * the signature — trading the old inline type links for consistent theming (including dark mode)
 * and real Prism highlighting.
 */
export default function PluginGoDocs() {
  if (!docs) {
    return <MissingDataNotice />;
  }

  const hasHelpers = (docs.Helpers?.Methods?.length ?? 0) > 0;

  return (
    <div className={styles.pluginGoDocs}>
      {docs.HTML && <div dangerouslySetInnerHTML={{__html: docs.HTML}} />}
      <InterfaceOverview name="API" iface={docs.API} />
      <InterfaceOverview name="Hooks" iface={docs.Hooks} />
      {hasHelpers && <InterfaceOverview name="Helpers" iface={docs.Helpers} />}
      <ExamplesTOC examples={docs.Examples} />
      <hr />
      <InterfaceMethodDocs name="API" iface={docs.API} />
      <hr />
      <InterfaceMethodDocs name="Hooks" iface={docs.Hooks} />
      {hasHelpers && (
        <>
          <hr />
          <InterfaceMethodDocs name="Helpers" iface={docs.Helpers} />
        </>
      )}
      <hr />
      <ExamplesDocs examples={docs.Examples} />
    </div>
  );
}
